import { readFile } from "node:fs/promises";

const form = new FormData();
form.append("file", new Blob([await readFile("audio.wav")], { type: "audio/wav" }), "audio.wav");
form.append("model", "{{MODEL}}");
form.append("response_format", "json");

const resp = await fetch("{{BASE_URL}}/v1/audio/translations", {
  method: "POST",
  headers: { "Authorization": "Bearer {{API_KEY}}" },
  body: form,
});
const body = await resp.json();
if (!resp.ok) throw new Error(`${body.error.code}: ${body.error.message}`);
console.log(body.text);

